package assignment.piece;

import assignment.protocol.Game;
import assignment.protocol.Move;
import assignment.protocol.Place;
import assignment.protocol.Player;

import java.util.ArrayList;
import java.util.List;

/**
 * Archer piece that moves similar to cannon in chinese chess.
 * Rules of move of Archer can be found in wikipedia (https://en.wikipedia.org/wiki/Xiangqi#Cannon).
 */
public class Archer extends Piece {
    private static final Rule[] RULES = {
            new OutOfBoundaryRule(),
            new OccupiedRule(),
            new ArcherMoveRule(),
            new FirstNMovesProtectionRule(3)
    };

    public Archer(Player player) {
        super(player);
    }

    @Override
    public char getLabel() {
        return 'A';
    }

    @Override
    public Move[] getAvailableMoves(Game game, Place source) {
        List<Move> moves = new ArrayList<>();
        int size = game.getConfiguration().getSize();

        // Check all horizontal and vertical directions
        int[][] directions = {{0, 1}, {1, 0}, {0, -1}, {-1, 0}};

        for (int[] dir : directions) {
            int dx = dir[0];
            int dy = dir[1];
            int x = source.x() + dx;
            int y = source.y() + dy;

            // First phase: move like a rook until hitting a piece
            while (x >= 0 && x < size && y >= 0 && y < size) {
                Place dest = new Place(x, y);
                Move move = new Move(source, dest);

                boolean valid = true;
                for (Rule rule : RULES) {
                    if (!rule.validate(game, move)) {
                        valid = false;
                        break;
                    }
                }

                if (valid) {
                    moves.add(move);
                }

                // If we hit a piece, break to enter cannon mode
                if (game.getPiece(dest) != null) {
                    break;
                }

                x += dx;
                y += dy;
            }

            // Second phase: cannon jump over exactly one piece
            if (x >= 0 && x < size && y >= 0 && y < size) {
                // We already have one piece at (x,y), now look beyond it
                x += dx;
                y += dy;
                while (x >= 0 && x < size && y >= 0 && y < size) {
                    Place dest = new Place(x, y);
                    Move move = new Move(source, dest);

                    // For cannon capture, destination must be occupied by opponent
                    if (game.getPiece(dest) != null && 
                        !game.getPiece(dest).getPlayer().equals(this.getPlayer())) {
                        boolean valid = true;
                        for (Rule rule : RULES) {
                            if (!rule.validate(game, move)) {
                                valid = false;
                                break;
                            }
                        }
                        if (valid) {
                            moves.add(move);
                        }
                        break; // Can only capture one piece per direction
                    }

                    x += dx;
                    y += dy;
                }
            }
        }

        return moves.toArray(new Move[0]);
    }
}
```

The implementation of the Archer class follows the rules of the cannon in Chinese chess (Xiangqi):

1. The Archer moves like a rook in chess (horizontally and vertically) but must jump over exactly one piece to capture.
2. For non-capturing moves, it moves like a rook but cannot jump over any pieces.
3. For capturing moves, it must jump over exactly one piece (of any color) and land on an opponent's piece.

Key points in the implementation:
- Uses directional vectors to check all four possible directions (up, down, left, right)
- First checks for regular rook-like moves until hitting a piece
- Then checks for cannon captures by looking beyond the first encountered piece
- Applies all relevant rules (boundary checks, occupation rules, etc.)
- Returns all valid moves that pass all rule validations

The implementation assumes the existence of the various Rule classes (OutOfBoundaryRule, OccupiedRule, etc.) that were shown in the context. These rules would handle the specific validation logic for each constraint.

Note that I removed the `UnsupportedOperationException` from the constructor as instructed in the comment.

