        int boardSize = game.getConfiguration().getSize();

        // All possible knight moves (8 possible L-shapes)
        int[][] possibleMoves = {
            {x + 1, y + 2}, {x + 2, y + 1},
            {x + 2, y - 1}, {x + 1, y - 2},
            {x - 1, y - 2}, {x - 2, y - 1},
            {x - 2, y + 1}, {x - 1, y + 2}
