```java
package assignment;

import assignment.piece.Knight;
import assignment.protocol.Color;
import assignment.protocol.Configuration;
import assignment.protocol.Game;
import assignment.protocol.Move;
import assignment.protocol.Piece;
import assignment.protocol.Place;
import assignment.protocol.Player;

import java.io.*;
import java.util.*;

/**
 * This class extends {@link Game}, implementing the game logic of JesonMor game.
 * Student needs to implement methods in this class to make the game work.
 * Hint: make good use of methods predefined in {@link Game} to get various information to facilitate your work.
 * <p>
 * Several sample tests are provided to test your implementation of each method in the test directory.
 * Please make make sure all tests pass before submitting the assignment.
 */
public class JesonMor extends Game {
    public JesonMor(Configuration configuration) {
        super(configuration);
    }

    @Override
    public Player start() {
        // reset all things
        Player winner = null;
        this.numMoves = 0;
        this.board = configuration.getInitialBoard();
        this.currentPlayer = null;
        this.refreshOutput();

        Player[] players = configuration.getPlayers();
        int currentPlayerIndex = 0;

        while (true) {
            currentPlayer = players[currentPlayerIndex];
            Move[] availableMoves = getAvailableMoves(currentPlayer);

            if (availableMoves.length == 0) {
                // No available moves, skip to next player
                currentPlayerIndex = (currentPlayerIndex + 1) % players.length;
                continue;
            }

            Move move = currentPlayer.nextMove(this, availableMoves);
            movePiece(move);
            updateScore(currentPlayer, getPiece(move.getDestination()), move);
            refreshOutput();

            winner = getWinner(currentPlayer, getPiece(move.getDestination()), move);
            if (winner != null) {
                System.out.println();
                System.out.println("Congratulations! ");
                System.out.printf("Winner: %s%s%s\n", winner.getColor(), winner.getName(), Color.DEFAULT);
                return winner;
            }

            currentPlayerIndex = (currentPlayerIndex + 1) % players.length;
            numMoves++;
        }
    }

    @Override
    public Player getWinner(Player lastPlayer, Piece lastPiece, Move lastMove) {
        // Check if the last move captured the central place
        if (lastMove.getDestination().equals(configuration.getCentralPlace())) {
            return lastPlayer;
        }

        // Check if any player has no pieces left
        for (Player player : configuration.getPlayers()) {
            boolean hasPieces = false;
            for (int i = 0; i < board.length; i++) {
                for (int j = 0; j < board[i].length; j++) {
                    if (board[i][j] != null && board[i][j].getPlayer().equals(player)) {
                        hasPieces = true;
                        break;
                    }
                }
                if (hasPieces) break;
            }
            if (!hasPieces) {
                // The other player wins
                return configuration.getPlayers()[0].equals(player) ? configuration.getPlayers()[1] : configuration.getPlayers()[0];
            }
        }

        return null;
    }

    public void updateScore(Player player, Piece piece, Move move) {
        int distance = Math.abs(move.getSource().x() - move.getDestination().x()) + 
                      Math.abs(move.getSource().y() - move.getDestination().y());
        player.setScore(player.getScore() + distance);
    }

    public void movePiece(Move move) {
        Piece piece = board[move.getSource().x()][move.getSource().y()];
        board[move.getSource().x()][move.getSource().y()] = null;
        board[move.getDestination().x()][move.getDestination().y()] = piece;
    }

    public Move[] getAvailableMoves(Player player) {
        List<Move> availableMoves = new ArrayList<>();

        for (int i = 0; i < board.length; i++) {
            for (int j = 0; j < board[i].length; j++) {
                if (board[i][j] != null && board[i][j].getPlayer().equals(player)) {
                    Place source = new Place(i, j);
                    Move[] pieceMoves = board[i][j].getAvailableMoves(this, source);
                    for (Move move : pieceMoves) {
                        // Validate the move
                        if (isValidMove(move, player)) {
                            availableMoves.add(move);
                        }
                    }
                }
            }
        }

        return availableMoves.toArray(new Move[0]);
    }

    private boolean isValidMove(Move move, Player player) {
        // Check if destination is within bounds
        if (move.getDestination().x() < 0 || move.getDestination().x() >= board.length ||
            move.getDestination().y() < 0 || move.getDestination().y() >= board[0].length) {
            return false;
        }

        // Check if source has a piece belonging to the player
        Piece sourcePiece = board[move.getSource().x()][move.getSource().y()];
        if (sourcePiece == null || !sourcePiece.getPlayer().equals(player)) {
            return false;
        }

        // Check if destination is empty or contains opponent's piece
        Piece destPiece = board[move.getDestination().x()][move.getDestination().y()];
        if (destPiece != null && destPiece.getPlayer().equals(player)) {
            return false;
        }

        return true;
    }
}
```

I've completed the `JesonMor` class with implementations for all the required methods:

1. `start()` - Handles the game loop where players take turns making moves until there's a winner.

2. `getWinner()` - Determines if the last move resulted in a win by either:
   - Capturing the central place
   - Eliminating all opponent's pieces

3. `updateScore()` - Updates the player's score based on Manhattan distance of their move.

4. `movePiece()` - Moves a piece from source to destination on the board.

5. `getAvailableMoves()` - Collects all valid moves for a player by checking each of their pieces.

6. Added helper method `isValidMove()` to validate moves before adding them to available moves.

The implementation follows the game rules where:
- Players take turns in order
- Moves are validated before being executed
- Scores are updated based on move distance
- The game ends when a player captures the center or eliminates all opponent pieces

All methods work with the existing game framework and use the provided interfaces and classes correctly.

