```java
package assignment;

import assignment.piece.Knight;
import assignment.protocol.Color;
import assignment.protocol.Configuration;
import assignment.protocol.Game;
import assignment.protocol.Move;
import assignment.protocol.Piece;
import assignment.protocol.Place;
import assignment.protocol.Player;

import java.io.*;
import java.util.*;

public class JesonMor extends Game {
    public JesonMor(Configuration configuration) {
        super(configuration);
    }

    @Override
    public Player start() {
        // reset all things
        Player winner = null;
        this.numMoves = 0;
        this.board = configuration.getInitialBoard();
        this.currentPlayer = null;
        this.refreshOutput();

        Player[] players = configuration.getPlayers();
        int currentPlayerIndex = 0;

        while (true) {
            currentPlayer = players[currentPlayerIndex];
            Move[] availableMoves = getAvailableMoves(currentPlayer);

            if (availableMoves.length == 0) {
                // No moves available for current player, skip turn
                currentPlayerIndex = (currentPlayerIndex + 1) % players.length;
                continue;
            }

            Move move = currentPlayer.nextMove(this, availableMoves);
            Piece movedPiece = getPiece(move.getSource());

            movePiece(move);
            updateScore(currentPlayer, movedPiece, move);
            numMoves++;
            refreshOutput();

            winner = getWinner(currentPlayer, movedPiece, move);
            if (winner != null) {
                System.out.println();
                System.out.println("Congratulations! ");
                System.out.printf("Winner: %s%s%s\n", winner.getColor(), winner.getName(), Color.DEFAULT);
                return winner;
            }

            currentPlayerIndex = (currentPlayerIndex + 1) % players.length;
        }
    }

    @Override
    public Player getWinner(Player lastPlayer, Piece lastPiece, Move lastMove) {
        // Check if the last move captured the central place
        Place centralPlace = getCentralPlace();
        if (lastMove.getDestination().equals(centralPlace)) {
            return lastPlayer;
        }
        return null;
    }

    @Override
    public void updateScore(Player player, Piece piece, Move move) {
        Place source = move.getSource();
        Place destination = move.getDestination();
        int distance = Math.abs(source.x() - destination.x()) + Math.abs(source.y() - destination.y());
        player.setScore(player.getScore() + distance);
    }

    @Override
    public void movePiece(Move move) {
        Place source = move.getSource();
        Place destination = move.getDestination();
        Piece piece = board[source.x()][source.y()];
        board[source.x()][source.y()] = null;
        board[destination.x()][destination.y()] = piece;
    }

    @Override
    public Move[] getAvailableMoves(Player player) {
        List<Move> allMoves = new ArrayList<>();
        int size = configuration.getSize();

        // Iterate through the board to find all pieces belonging to the player
        for (int x = 0; x < size; x++) {
            for (int y = 0; y < size; y++) {
                Piece piece = board[x][y];
                if (piece != null && piece.getPlayer().equals(player)) {
                    Place source = new Place(x, y);
                    Move[] pieceMoves = piece.getAvailableMoves(this, source);
                    for (Move move : pieceMoves) {
                        // Validate that the move is within bounds
                        Place dest = move.getDestination();
                        if (dest.x() >= 0 && dest.x() < size && dest.y() >= 0 && dest.y() < size) {
                            allMoves.add(move);
                        }
                    }
                }
            }
        }

        return allMoves.toArray(new Move[0]);
    }
}
```

This implementation includes:

1. **start()**: 
   - Initializes the game state
   - Alternates turns between players
   - Gets available moves for current player
   - Executes moves and updates game state
   - Checks for winner after each move

2. **getWinner()**:
   - Checks if the last move captured the central place (win condition)

3. **updateScore()**:
   - Calculates Manhattan distance between source and destination
   - Updates player's score accordingly

4. **movePiece()**:
   - Moves a piece from source to destination on the board
   - Removes piece from source location

5. **getAvailableMoves()**:
   - Collects all valid moves for all pieces belonging to the player
   - Ensures moves are within board boundaries

The implementation follows the game rules where:
- Players take turns moving their pieces
- The game ends when a player captures the central place
- Scores are calculated based on Manhattan distance of moves
- All moves are validated to be within board boundaries

The code maintains proper encapsulation and uses the provided interfaces and classes from the protocol package.

