package assignment;

import assignment.piece.Knight;
import assignment.protocol.Color;
import assignment.protocol.Configuration;
import assignment.protocol.Game;
import assignment.protocol.Move;
import assignment.protocol.Piece;
import assignment.protocol.Place;
import assignment.protocol.Player;

import java.io.*;
import java.util.*;

/**
 * This class extends {@link Game}, implementing the game logic of JesonMor game.
 * Student needs to implement methods in this class to make the game work.
 * Hint: make good use of methods predefined in {@link Game} to get various information to facilitate your work.
 * <p>
 * Several sample tests are provided to test your implementation of each method in the test directory.
 * Please make make sure all tests pass before submitting the assignment.
 */
public class JesonMor extends Game {
    public JesonMor(Configuration configuration) {
        super(configuration);
    }

    @Override
    public Player start() {
        // reset all things
        Player winner = null;
        this.numMoves = 0;
        this.board = configuration.getInitialBoard();
        this.currentPlayer = null;
        this.refreshOutput();

        Player[] players = configuration.getPlayers();
        int currentPlayerIndex = 0;

        while (true) {
            currentPlayer = players[currentPlayerIndex];
            Move[] availableMoves = getAvailableMoves(currentPlayer);

            if (availableMoves.length == 0) {
                // No available moves, skip this player's turn
                currentPlayerIndex = (currentPlayerIndex + 1) % players.length;
                continue;
            }

            Move move = currentPlayer.nextMove(this, availableMoves);
            movePiece(move);
            updateScore(currentPlayer, getPiece(move.getDestination()), move);
            numMoves++;
            refreshOutput();

            winner = getWinner(currentPlayer, getPiece(move.getDestination()), move);
            if (winner != null) {
                System.out.println();
                System.out.println("Congratulations! ");
                System.out.printf("Winner: %s%s%s\n", winner.getColor(), winner.getName(), Color.DEFAULT);
                return winner;
            }

            currentPlayerIndex = (currentPlayerIndex + 1) % players.length;
        }
    }

    @Override
    public Player getWinner(Player lastPlayer, Piece lastPiece, Move lastMove) {
        // Check if the moved piece is a Knight and reached the central place
        if (lastPiece instanceof Knight && lastMove.getDestination().equals(configuration.getCentralPlace())) {
            return lastPlayer;
        }
        return null;
    }

    public void updateScore(Player player, Piece piece, Move move) {
        int distance = Math.abs(move.getDestination().x() - move.getSource().x()) + 
                      Math.abs(move.getDestination().y() - move.getSource().y());
        player.setScore(player.getScore() + distance);
    }

    public void movePiece(Move move) {
        Piece piece = getPiece(move.getSource());
        board[move.getSource().x()][move.getSource().y()] = null;
        board[move.getDestination().x()][move.getDestination().y()] = piece;
    }

    public Move[] getAvailableMoves(Player player) {
        List<Move> availableMoves = new ArrayList<>();
        int size = configuration.getSize();

        // Iterate through the board to find all pieces belonging to the player
        for (int x = 0; x < size; x++) {
            for (int y = 0; y < size; y++) {
                Piece piece = board[x][y];
                if (piece != null && piece.getPlayer().equals(player)) {
                    Place source = new Place(x, y);
                    Move[] pieceMoves = piece.getAvailableMoves(this, source);
                    for (Move move : pieceMoves) {
                        // Validate the move is within bounds and not occupied by same player
                        Place dest = move.getDestination();
                        if (dest.x() >= 0 && dest.x() < size && 
                            dest.y() >= 0 && dest.y() < size) {
                            Piece destPiece = board[dest.x()][dest.y()];
                            if (destPiece == null || !destPiece.getPlayer().equals(player)) {
                                availableMoves.add(move);
                            }
                        }
                    }
                }
            }
        }

        return availableMoves.toArray(new Move[0]);
    }
}
```

This implementation:

1. `start()` method:
   - Initializes the game state
   - Alternates turns between players
   - Gets available moves for current player
   - Executes the chosen move
   - Updates score and checks for winner after each move

2. `getWinner()` method:
   - Checks if a Knight piece reached the central place
   - Returns the winning player if condition is met

3. `updateScore()` method:
   - Calculates Manhattan distance between source and destination
   - Updates player's score with this distance

4. `movePiece()` method:
   - Moves piece from source to destination on the board
   - Clears the source position

5. `getAvailableMoves()` method:
   - Collects all valid moves for all pieces belonging to the player
   - Validates moves are within bounds and not blocked by same player's pieces

The implementation follows the game rules where:
- Players take turns moving their pieces
- The goal is to move a Knight to the central place
- Score is calculated based on movement distance
- Only valid moves are allowed (within bounds and not blocked by own pieces)

