     * @param size               size of gameboard
     * @param numMovesProtection number of moves with capture protection
     * @return the game object
     */
    public static Game createGame(int size, int numMovesProtection) {
        // Create players
        ConsolePlayer userPlayer = new ConsolePlayer("User", Player.Color.BLACK);
        RandomPlayer computerPlayer = new RandomPlayer("Computer", Player.Color.WHITE);

        // Create configuration with players
        Configuration configuration = new Configuration(size, new Player[]{userPlayer, computerPlayer}, numMovesProtection);

        // Calculate center position
        int center = size / 2;
        configuration.setCentralPlace(new Place(center, center));

        // Initialize pieces for user (BLACK)
        configuration.addInitialPiece(new Knight(userPlayer), 0, 0);
        configuration.addInitialPiece(new Knight(userPlayer), 0, size-1);
        configuration.addInitialPiece(new Archer(userPlayer), 1, 0);
        configuration.addInitialPiece(new Archer(userPlayer), 1, size-1);

        // Initialize pieces for computer (WHITE)
        configuration.addInitialPiece(new Knight(computerPlayer), size-1, 0);
        configuration.addInitialPiece(new Knight(computerPlayer), size-1, size-1);
        configuration.addInitialPiece(new Archer(computerPlayer), size-2, 0);
        configuration.addInitialPiece(new Archer(computerPlayer), size-2, size-1);

        return new JesonMor(configuration);
    }

