        // Initialize pieces for computer player (black)
        configuration.addInitialPiece(new Archer(computerPlayer), size-1, 0);
        configuration.addInitialPiece(new Knight(computerPlayer), size-1, size-1);

        return new JesonMor(configuration);
    }

    public static void main(String[] args) {
        // Validate arguments
        if (args.length < 2) {
            throw new IllegalArgumentException(
                "Two integer arguments are required specifying size of gameboard and number of moves with capturing protection");
