            if (numMovesProtection < 0) {
                throw new IllegalArgumentException("Number of protection moves cannot be negative");
            }
        } catch (NumberFormatException e) {
            throw new IllegalArgumentException("Second argument must be a number");
        }

        // Create and start the game
        Game game = createGame(size, numMovesProtection);
        game.start();
    }
}
