        // Check if move is orthogonal
        if (source.x() != destination.x() && source.y() != destination.y()) {
            return false;
        }

        Piece destinationPiece = game.getPiece(destination);
        boolean isCaptureMove = destinationPiece != null;

        int dx = Integer.compare(destination.x(), source.x());
        int dy = Integer.compare(destination.y(), source.y());

        int x = source.x() + dx;
        int y = source.y() + dy;
        int piecesInPath = 0;

        // Count pieces in the path
        while (x != destination.x() || y != destination.y()) {
            if (game.getPiece(x, y) != null) {
