package assignment.piece;

import assignment.protocol.Game;
import assignment.protocol.Move;
import assignment.protocol.Place;

/**
 * The blocking rule applying on Knights. The rule is similar to the blocking rule for horse in Chinese chess.
 * The horse does not jump as the knight does in Western chess, and can be blocked by a piece of either colour located one point horizontally or vertically adjacent to it
 */
public class KnightBlockRule implements Rule {
    @Override
    public boolean validate(Game game, Move move) {
        if (!(game.getPiece(move.getSource()) instanceof Knight)) {
            return true;
        }

        Place source = move.getSource();
        Place destination = move.getDestination();

        // Calculate the difference between source and destination
        int dx = destination.x() - source.x();
        int dy = destination.y() - source.y();

        // Check if the move is a valid knight move (L-shape)
        if (!((Math.abs(dx) == 2 && Math.abs(dy) == 1) || 
              (Math.abs(dx) == 1 && Math.abs(dy) == 2))) {
            return true; // Not a knight move, so this rule doesn't apply
        }

        // Determine the blocking position based on the move direction
        int blockX = source.x();
        int blockY = source.y();

        if (Math.abs(dx) == 2) {
            // Horizontal L-shape, check vertical blocking
            blockX += dx / 2;
        } else {
            // Vertical L-shape, check horizontal blocking
            blockY += dy / 2;
        }

        // Check if there's a piece at the blocking position
        return game.getPiece(blockX, blockY) == null;
    }

    @Override
    public String getDescription() {
        return "knight is blocked by another piece";
    }
}
```

