package assignment.piece;

import assignment.protocol.Game;
import assignment.protocol.Move;
import assignment.protocol.Place;

/**
 * Global rule that requires the source and destination should be inside the board boundary.
 */
public class OutOfBoundaryRule implements Rule {
    @Override
    public boolean validate(Game game, Move move) {
        int boardSize = game.getConfiguration().getSize();
        Place source = move.getSource();
        Place destination = move.getDestination();

        // Check if source is within bounds
        boolean sourceValid = isWithinBounds(source, boardSize);
        // Check if destination is within bounds
        boolean destinationValid = isWithinBounds(destination, boardSize);

        // Both source and destination must be within bounds
        return sourceValid && destinationValid;
    }

    @Override
    public String getDescription() {
        return "place is out of boundary of gameboard";
    }

    /**
     * Helper method to check if a place is within the game board boundaries
     * @param place The place to check
     * @param boardSize The size of the game board
     * @return true if the place is within bounds, false otherwise
     */
    private boolean isWithinBounds(Place place, int boardSize) {
        int x = place.x();
        int y = place.y();
        return x >= 0 && x < boardSize && y >= 0 && y < boardSize;
    }
}
```

